/**
 * Industrial Warehouse navigation data: spawns, nodes, explicit links, routes, cover and
 * patrol points (business-logic-model-warehouse-map, "Nav data derivation"). Same-level
 * links between nearby nodes are generated by buildNavGraph; every route step is an explicit
 * link here, and the four ramp steps are 'ramp' links (BR-WH-22).
 */
import { vec3, type Vec3 } from '@sz/kernel';
import { chain, coverBeside, linkChain, node } from './build';
import type {
  CoverPoint,
  NavLinkDef,
  NavNodeDef,
  NavNodeTag,
  PatrolPoint,
  RouteDef,
  Solid,
  SpawnPoint,
} from './types';
import { COVER_PROPS, DECK_TOP } from './warehouse-solids';

const at = (x: number, z: number): Vec3 => vec3(x, 0, z);
const RAMP_MID_Y = DECK_TOP / 2;

// ---- spawns (BR-WH-30) ----
const PLAYER_SPAWN_X = [-14, -8, -4, 4, 8, 14] as const;
const BOT_AREAS = [
  { area: 'nw-bay', xs: [-34, -29, -24, -19, -14, -9] },
  { area: 'ne-bay', xs: [9, 14, 19, 24, 29, 34] },
] as const;
const BOT_SPAWN_Z = [-34, -38] as const;

export const WAREHOUSE_PLAYER_SPAWNS: ReadonlyArray<SpawnPoint> = PLAYER_SPAWN_X.map((x, i) => ({
  id: `player-${String(i + 1)}`,
  area: 'south-bay',
  pos: at(x, 35),
  yaw: 0, // facing north (-Z)
}));

export const WAREHOUSE_BOT_SPAWNS: ReadonlyArray<SpawnPoint> = BOT_AREAS.flatMap(({ area, xs }) =>
  BOT_SPAWN_Z.flatMap((z) => xs.map((x) => at(x, z))).map((pos, i) => ({
    id: `${area}-${String(i + 1)}`,
    area,
    pos,
    yaw: Math.PI, // facing south (+Z)
  })),
);

// ---- bay grids ----
const SOUTH_X = [-36, -28, -20, -14, -8, -4, 0, 4, 8, 14, 20, 28.6, 36] as const;
const SOUTH_Z = [31, 35, 38] as const;
const NORTH_X = [-34, -29, -24, -19, -14, -9, -4, 0, 4, 9, 14, 19, 24, 29, 34] as const;
const NORTH_Z = [-31, -34, -38] as const;

const southId = (x: number, z: number) => `bay-s-${String(x)}-${String(z)}`;
const northId = (x: number, z: number) => `bay-n-${String(x)}-${String(-z)}`;

const posKey = (p: Vec3) => `${String(p.x)},${String(p.z)}`;
const PLAYER_SPAWN_KEYS = new Set(WAREHOUSE_PLAYER_SPAWNS.map((s) => posKey(s.pos)));
const BOT_SPAWN_KEYS = new Set(WAREHOUSE_BOT_SPAWNS.map((s) => posKey(s.pos)));

function grid(
  xs: ReadonlyArray<number>,
  zs: ReadonlyArray<number>,
  name: (x: number, z: number) => string,
  spawnKeys: ReadonlySet<string>,
  spawnTag: NavNodeTag,
): NavNodeDef[] {
  return zs.flatMap((z) =>
    xs.map((x) => {
      const tags: NavNodeTag[] = spawnKeys.has(posKey(at(x, z))) ? [spawnTag] : [];
      return node(name(x, z), at(x, z), ...tags);
    }),
  );
}

// ---- route chains ----
const WEST = chain('west', at(-28, 26), at(-28, -26), 6.5, 'corridor');

const MAIN_ROUTE: ReadonlyArray<NavNodeDef> = [
  at(0, 26),
  at(-7.5, 26),
  ...[19, 12, 5, -2, -9, -16, -22].map((z) => at(-7.5, z)),
  at(-7.5, -26),
  at(0, -26),
].map((p, i) => node(`main-${String(i)}`, p));

const GANTRY_ROUTE: ReadonlyArray<NavNodeDef> = [
  node('gantry-0', at(28.6, 26)),
  node('gantry-1', at(28.6, 24)), // south ramp foot
  node('gantry-2', vec3(28.6, RAMP_MID_Y, 19)), // south ramp middle
  ...[14, 7, 0, -7, -14].map((z, i) =>
    node(`gantry-${String(i + 3)}`, vec3(28.6, DECK_TOP, z), 'elevated'),
  ),
  node('gantry-8', vec3(28.6, RAMP_MID_Y, -19)), // north ramp middle
  node('gantry-9', at(28.6, -24)), // north ramp foot
  node('gantry-10', at(28.6, -26)),
];

// ---- non-route lanes (automatic links only) ----
const FLOOR_EAST = chain('floor-east', at(7.5, 26), at(7.5, -26), 6.5);
const FLOOR_MIDDLE = [
  node('floor-mid-s2', at(0, 17)),
  node('floor-mid-s1', at(0, 6)),
  node('floor-mid-n1', at(0, -6)),
  node('floor-mid-n2', at(0, -17)),
];
const AISLE_W = chain('aisle-w', at(-20, 22), at(-20, -22), 7.5);
const AISLE_E = chain('aisle-e', at(21, 22), at(21, -22), 7.5);

// ---- cover points (BR-WH-23: exactly 34) ----
type Side = 'n' | 's' | 'e' | 'w';
const NS: ReadonlyArray<Side> = ['n', 's'];
const COVER_PLAN: ReadonlyArray<readonly [Solid, ReadonlyArray<Side>]> = [
  [COVER_PROPS.floorCrate0, NS],
  [COVER_PROPS.floorCrate1, NS],
  [COVER_PROPS.floorCrate2, NS],
  [COVER_PROPS.floorCrate3, NS],
  [COVER_PROPS.floorCrate4, NS],
  [COVER_PROPS.floorCrate5, NS],
  [COVER_PROPS.floorCrate6, NS],
  [COVER_PROPS.floorCrate7, NS],
  [COVER_PROPS.barrierSw, NS],
  [COVER_PROPS.barrierSe, NS],
  [COVER_PROPS.barrierNw, NS],
  [COVER_PROPS.barrierNe, NS],
  [COVER_PROPS.press, ['n', 's', 'e', 'w']],
  [COVER_PROPS.parapet0, ['e']],
  [COVER_PROPS.parapet1, ['e']],
  [COVER_PROPS.parapet2, ['e']],
  [COVER_PROPS.parapet3, ['e']],
  [COVER_PROPS.containerE1, ['e']],
  [COVER_PROPS.containerE2, ['e']],
];

const COVER_GAP = 0.9;
/** Solids lower than this only hide a crouching bot. */
const CROUCH_ONLY_BELOW = 1.5;

export const WAREHOUSE_COVER_POINTS: ReadonlyArray<CoverPoint> = COVER_PLAN.flatMap(
  ([solid, sides]) =>
    sides.map((side) =>
      coverBeside(`cover-${solid.id}-${side}`, solid, side, {
        gap: COVER_GAP,
        crouchOnly: solid.half.y * 2 < CROUCH_ONLY_BELOW,
      }),
    ),
);

const COVER_NODES = WAREHOUSE_COVER_POINTS.map((c) => node(c.id, c.pos, 'cover'));

// ---- patrol points (BR-WH-25: one or more in every lane region) ----
const PATROL_NODE_IDS: ReadonlyArray<string> = [
  'west-2',
  'west-6',
  'main-3',
  'main-7',
  'aisle-w-1',
  'aisle-w-5',
  'aisle-e-1',
  'aisle-e-5',
  'floor-east-4',
  'gantry-5',
  northId(-19, -31),
  northId(19, -31),
];
const PATROL_SET = new Set(PATROL_NODE_IDS);

function withPatrolTags(nodes: ReadonlyArray<NavNodeDef>): NavNodeDef[] {
  return nodes.map((n) => (PATROL_SET.has(n.id) ? { ...n, tags: [...n.tags, 'patrol'] } : n));
}

export const WAREHOUSE_NAV_NODES: ReadonlyArray<NavNodeDef> = withPatrolTags([
  ...grid(SOUTH_X, SOUTH_Z, southId, PLAYER_SPAWN_KEYS, 'spawn-player'),
  ...grid(NORTH_X, NORTH_Z, northId, BOT_SPAWN_KEYS, 'spawn-bot'),
  ...WEST,
  ...MAIN_ROUTE,
  ...GANTRY_ROUTE,
  ...FLOOR_EAST,
  ...FLOOR_MIDDLE,
  ...AISLE_W,
  ...AISLE_E,
  ...COVER_NODES,
]);

const nodeById = new Map(WAREHOUSE_NAV_NODES.map((n) => [n.id, n]));

export const WAREHOUSE_PATROL_POINTS: ReadonlyArray<PatrolPoint> = PATROL_NODE_IDS.flatMap((id) => {
  const n = nodeById.get(id);
  return n ? [{ id: `patrol-${id}`, pos: n.pos }] : [];
});

// ---- routes (BR-WH-21: exactly three, interiors share no node) ----
const ids = (nodes: ReadonlyArray<NavNodeDef>) => nodes.map((n) => n.id);

export const WAREHOUSE_ROUTES: ReadonlyArray<RouteDef> = [
  {
    id: 'west-containers',
    name: 'West Container Rows',
    nodes: [southId(-28, 31), ...ids(WEST), northId(-29, -31)],
  },
  {
    id: 'main-floor',
    name: 'Main Floor',
    nodes: [southId(0, 31), ...ids(MAIN_ROUTE), northId(0, -31)],
  },
  {
    id: 'east-gantry',
    name: 'East Gantry',
    nodes: [southId(28.6, 31), ...ids(GANTRY_ROUTE), northId(29, -31)],
  },
];

const RAMP_STEPS: ReadonlyArray<readonly [string, string]> = [
  ['gantry-1', 'gantry-2'],
  ['gantry-2', 'gantry-3'],
  ['gantry-7', 'gantry-8'],
  ['gantry-8', 'gantry-9'],
];
const RAMP_KEYS = new Set(RAMP_STEPS.map(([a, b]) => `${a}|${b}`));

/** Every route step is explicit; ramp steps are 'ramp' links. */
export const WAREHOUSE_NAV_LINKS: ReadonlyArray<NavLinkDef> = WAREHOUSE_ROUTES.flatMap((r) =>
  linkChain(r.nodes).map((l) =>
    RAMP_KEYS.has(`${l.a}|${l.b}`) ? { ...l, kind: 'ramp' as const } : l,
  ),
);
